cat > src/claim-office.spec.ts <<'EOF'
import { describe, it } from "vitest";

describe("MHPCO Claim Office", () => {
  // --- Quote: base premiums for single items ---
  it.todo("quotes an empty item list -- premium 5 G (processing fee only)");
  it.todo("quotes a single plain sword -- base 100 G + 10 G first insurance + 5 G fee = 115 G");
  it.todo("quotes a single plain amulet -- base 60 G + 6 G first insurance + 5 G fee = 71 G");
  it.todo("quotes a single plain staff -- base 80 G + 8 G first insurance + 5 G fee = 93 G");
  it.todo("quotes a single plain potion -- base 40 G + 4 G first insurance + 5 G fee = 49 G");
  it.todo("quotes a single rune -- base 25 G + 2.5 G first insurance + 5 G fee = 33 G (rounded up in MHPCO's favor)");
  it.todo("quotes a single moonstone -- base 25 G + 2.5 G first insurance + 5 G fee = 33 G");

  // --- Building block of 3 alike components ---
  it.todo("quotes 2 runes -- base premium 50 G (no block)");
  it.todo("quotes 3 runes -- base premium 60 G (block applies)");
  it.todo("quotes 4 runes -- base premium 100 G (no block; block requires exactly 3)");
  it.todo("quotes 7 runes -- base premium 175 G (no block; 7 is not a multiple of 3)");

  // --- 'Alike' means exactly the same component type ---
  it.todo("quotes 2 runes + 1 moonstone -- base premium 75 G (no block: different types)");
  it.todo("quotes 3 runes + 3 moonstones -- base premium 120 G (two separate blocks)");

  // --- Item-specific modifiers ---
  it.todo("quotes a cursed sword -- 50 % curse surcharge on the sword's base premium");
  it.todo("quotes a sword with enchantment 5 -- 30 % high-enchantment surcharge applies at the threshold");
  it.todo("quotes a sword with enchantment 4 -- no high-enchantment surcharge");
  it.todo("quotes a cursed sword with enchantment 5 -- both curse and high-enchantment surcharges apply");

  // --- Policy-wide modifiers ---
  it.todo("quotes for a customer with exactly 2 years with MHPCO -- 20 % loyalty discount applies");
  it.todo("quotes for a customer with 1 year with MHPCO -- no loyalty discount");
  it.todo("quotes a second contract -- 15 % follow-up discount on the policy base premium");
  it.todo("quotes a third contract -- 15 % follow-up discount applies to every contract after the first");
  it.todo("applies the 10 % first-insurance surcharge to each item in every quote, regardless of customer history");

  // --- Modifier scope on multi-item policies ---
  it.todo("quotes a cursed sword (100 G) + plain amulet (60 G) -- curse adds 50 G (50 % of the sword only) -> 210 G before further modifiers and fee");

  // --- Rounding in MHPCO's favor ---
  it.todo("rounds a premium of 197.5 G up to 198 G");
  it.todo("keeps intermediate premium amounts as fractions and rounds only the final premium");

  // --- Integration examples ---
  it.todo("integration: newcomer (0 years, no previous contract) with a cursed steel sword enchantment 3 -- premium 165 G");
  it.todo("integration: 3-year customer's second quote of a cursed steel sword enchantment 7 -- premium 160 G");

  // --- Quote validation ---
  it.todo("rejects a quote containing an unknown item type (e.g. broomstick) -- throws an Error (adopted reading: spec says CLI exits non-zero with stderr; domain signals via thrown Error)");

  // --- Claim: standard reimbursement ---
  it.todo("claims a regular steel sword enchantment 3 with damage 500 G -- payout 400 G (full reimbursement minus 100 G deductible)");
  it.todo("claims a rune with damage 200 G -- payout 100 G (no enchantment or material, so no special clause)");

  // --- Claim: special clauses ---
  it.todo("claims a steel sword enchantment 9 with damage 1000 G -- payout 400 G (50 % clause then deductible)");
  it.todo("claims a dragon-material sword enchantment 5 with damage 800 G -- payout 700 G (full reimbursement then deductible)");
  it.todo("claims a dragon-material sword enchantment 8 with damage 1000 G -- payout 400 G (50 % clause at the threshold, then deductible)");
  it.todo("claims a dragon-material sword enchantment 9 with damage 1000 G -- payout 400 G (the 50 % rule wins over full reimbursement)");

  // --- Deductible per damage event ---
  it.todo("claims a sword (500 G) and an amulet (300 G) in one incident -- payout 600 G (100 G deductible per damaged item)");

  // --- Payout rounding ---
  it.todo("rounds a payout of 350.5 G down to 350 G");

  // --- Insurance sum and cap ---
  it.todo("reports remainingCap 3200 G for a policy of a sword and an amulet before any claim (insurance sum 1600 G, cap 2×)");
  it.todo("bases the cap on unmodified insurance values -- cursed sword policy has cap 2000 G despite premium modifiers");
  it.todo("computes the insurance sum for a sword and 3 runes as 1750 G (cap 3500 G; the block discount affects the premium only)");
  it.todo("computes the insurance sum for two swords as 2000 G (cap 4000 G)");

  // --- Cap exhaustion across successive claims ---
  it.todo("claims 1500 G against a sword policy (cap 2000 G) -- payout 1400 G, remainingCap 600 G");
  it.todo("claims 1500 G twice against a sword policy -- second payout is reduced to the remaining cap 600 G, remainingCap 0 G");

  // --- Multiple items of the same type ---
  it.todo("treats two sword damage entries against a two-sword policy as separate damages, each with its own deductible");
  it.todo("rejects a claim with more damage entries of a type than the policy covers (two sword damages, one sword insured)");

  // --- Claim validation ---
  it.todo("rejects a claim for an item not covered by the policy (amulet damaged when only a sword is insured)");
  it.todo("rejects a claim for a damage entry with an unknown item type");
  it.todo("rejects a claim with a negative damage amount (amount: -200)");

  // --- Scenario processing ---
  it.todo("processes steps sequentially and returns results in the same order and length as the input steps");
  it.todo("resolves a claim's policy field as the zero-based index of the quote step that created the policy");
});

describe("claim-office CLI", () => {
  it.todo("reads the schema example scenario from stdin and writes {results: [{premium}, {payout, remainingCap}]} to stdout");
  it.todo("exits with a non-zero status and writes an error description to stderr for an unknown item type, writing no results to stdout");
  it.todo("exits with a non-zero status and writes an error description to stderr for a claim against an uninsured item");
  it.todo("exits with a non-zero status and writes an error description to stderr for a negative damage amount");
});
EOF
